import React from "react";
import { createRoot } from "react-dom/client";
import App from "./App";
import { SiteConfigProvider } from "@providers/SiteConfig";
import { ThemeProvider } from "@providers/Theme";
// NOTE: theme.css is generated by `npm run build:theme` from src/tokens (D-002). Never hand-edit it.
import "./styles/theme.css";
import "./styles/tooltip.css";
// @ts-expect-error SCSS is handled by the bundler at runtime.
import "./styles/main.scss";

// Escape dismisses tooltips (WCAG 1.4.13); they return when the pointer moves or focus changes.
document.addEventListener("keydown", (e) => {
  if (e.key === "Escape") document.documentElement.dataset.tooltipsHidden = "true";
});
["pointermove", "focusin"].forEach((type) =>
  document.addEventListener(type, () => {
    delete document.documentElement.dataset.tooltipsHidden;
  }),
);

const container = document.getElementById("root");
if (container) {
  const root = createRoot(container);
  root.render(
    <React.StrictMode>
      <ThemeProvider>
        <SiteConfigProvider config={{ isJobSeeking: true }}>
          <App />
        </SiteConfigProvider>
      </ThemeProvider>
    </React.StrictMode>,
  );
}
